begin;
create table if not exists collections(id bigint generated by default as identity primary key,name text not null,slug text unique not null,description text,image_url text,featured boolean default false,active boolean default true,created_at timestamptz default now());
create table if not exists occasions(id bigint generated by default as identity primary key,name text not null,slug text unique not null,image_url text,active boolean default true,created_at timestamptz default now());
create table if not exists collection_products(collection_id bigint references collections(id),product_id uuid references products(id),primary key(collection_id,product_id));
create table if not exists product_occasions(occasion_id bigint references occasions(id),product_id uuid references products(id),primary key(occasion_id,product_id));
alter table reviews add column if not exists visible boolean default true;
alter table reviews add column if not exists verified_purchase boolean default false;
alter table gift_cards add column if not exists issued_to text;
alter table artisans add column if not exists speciality text;
alter table artisans add column if not exists instagram text;
alter table faqs add column if not exists category text;
alter table orders add column if not exists internal_notes text;
alter table custom_requests add column if not exists listed_in_shop boolean default false;
create table if not exists testimonials(id bigint generated by default as identity primary key,name text not null,quote text not null,active boolean default true,created_at timestamptz default now());
do $$ declare t text; begin foreach t in array array['collections','occasions','collection_products','product_occasions','testimonials'] loop execute format('alter table %I enable row level security',t);execute format('revoke all on %I from anon,authenticated',t);end loop;end $$;
commit;
